       'Pryout of the group', dc('Pryout of the 2 shear'), '%.2f'; 'Breakout to a side face, case 1', dc('Shear breakout of the shear anchors towards a side face, case 1'), '%.2f';
       'Breakout to a side face, case 2', dc('Shear breakout of the shear anchors towards a side face, case 2'), '%.2f'};
