       'Shear, H only: largest ratio', St.s(1,:), '%.2f'; 'Tension, largest ratio', St.nT, '%.2f';
       'Tension + shear, H only (17.8.3, /1.2)', St.int(1,:), '%.2f';
       'If all 4 holes bear: tension + shear (information)', St.int(2,:), '%.2f'};
