% ---- 9. strut-and-tie models of the joint (ACI 318-19 chapter 23), written as small explicit steps
S6 = ca_stm(P, R, 0.6);  S8 = ca_stm(P, R, 0.8);  M = S6(1);  th = M.theta;  phi = 0.75;  q = M.p2;
Ase = an.Ase;  Ab12s = pi*P.cb.db^2/4;  Acol = pi*P.col.db^2/4;  rc = P.col.cover + P.col.dtie + P.col.db/2;
wV = bp.u - (P.col.b - rc - 8 - P.col.db/2);  An1 = 2*H.Abrg;  z1 = Y.zT;  z2 = M.z2;  Tk = M.T*kN;
xp = row('Pullout at the back plate');  xb = row('Side-face blowout');
ok_ = @(d) sprintf('<span class="%s">D/C = %.2f</span>', ifelse(d <= 1, 'ok', 'ng'), d);
w('<h2>9. Strut-and-tie models of the joint (ACI 318-19 chapter 23)</h2>');
w('<style>.st{border-collapse:collapse;margin:10px 0 14px 0;width:100%%;max-width:1000px}.st td{border:1px solid #ddd;padding:5px 9px;text-align:left;font-size:14.5px;line-height:1.5}.st td:first-child{width:95px;color:#555;background:#f6f6f6;font-size:13px}.st tr:first-child td{background:#eef3f8;font-weight:bold}.st tr:last-child td:last-child{font-weight:bold}</style>');
w(['<div class="calc" style="max-width:1000px"><p><b>In short.</b> A strut-and-tie model replaces the concrete of the joint by a truss: <b>struts</b> are concrete in compression, <b>ties</b> are steel in tension, ' ...
   '<b>nodes</b> are where they meet. If every part of one truss carries its force (23.3.1: &phi; &times; strength &ge; force, &phi; = 0.75, Table 21.2.1(g)), the joint is safe (a lower-bound result, R23.2.3). ' ...
   'R17.5.2.1 allows this method for the anchor reinforcement.</p>' ...
   '<p>Two trusses are checked, each carrying <b>all</b> of the pull on its own: <b>path 1</b> sends it into the beam top bars, <b>path 2</b> sends it diagonally down to the end plate''s push on the face. ' ...
   'If either one passes, the joint passes. Type E is worked out step by step; the other types are in the table of 9.4.</p></div>']);
w('<div class="row"><div><img src="figures/ta_stm.png" alt="STM"></div><div class="calc">');
w('<p><b>Starting numbers, type E</b></p><ul>');
w('<li>Pull on the two top anchors: <b>T = %.1f kN</b> (section 1)</li>', Tk);
w('<li>Anchors at z = %+g; back plate B1: %g high, %g wide, its bearing face at u = %g from the cantilever face</li>', z1, bp.h, bp.w, bp.u);
w('<li>Net bearing area of B1 (minus the 2 holes): %.0f mm&sup2;</li>', An1);
w('<li>Beam top bars (tie of path 1) at z = %g (the lower layer, conservative)</li>', z2);
w('<li>Concrete f''<sub>c</sub> = %.2f MPa; bars f<sub>y</sub> = %g MPa; anchors f<sub>ya</sub> = %g MPa</li>', fc, P.fy, an.fya);
w('</ul></div></div>');

% ---------------- path 1
w('<h3>9.1 Path 1: from the back plate into the beam top bars</h3><div class="calc" style="max-width:1000px">');
w(['<table class="st"><tr><td>Step 1</td><td>Choose the angle &theta; of the strut S1 (from B1 down to the beam bars)</td></tr>' ...
   '<tr><td>Rule</td><td>23.2.7: a strut must make at least 25&#176; with any tie at its node, so 25&#176; &le; &theta; &le; 65&#176; (the anchors and bars are horizontal, the column-bar tie is vertical). ' ...
   'Inside that range the designer may choose (R23.2.3, lower bound).</td></tr>' ...
   '<tr><td>How</td><td>Every angle from 25&#176; to 65&#176; was tried in 0.5&#176; steps. For each angle all the checks below were computed and the <b>worst</b> one noted. ' ...
   'The angle kept is the one whose worst check is <b>lowest</b> (that is what &ldquo;smallest largest D/C&rdquo; means). The checks at the anchor head (9.3) do not take part.</td></tr>' ...
   '<tr><td>Result</td><td>&theta; = %.1f&#176;</td></tr></table>'], th);
w(['<table class="st"><tr><td>Step 2</td><td>Forces in the truss</td></tr>' ...
   '<tr><td>Rule</td><td>Equilibrium at the back plate (23.2.4): the strut pushes back the pull T, so its horizontal part equals T: S1 cos&theta; = T. Its vertical part is held by the column bars: V = S1 sin&theta;.</td></tr>' ...
   '<tr><td>Numbers</td><td>S1 = T / cos&theta; = %.1f / cos %.1f&#176; = %.1f / %.3f = %.1f kN<br>V = T &times; tan&theta; = %.1f &times; tan %.1f&#176; = %.1f &times; %.3f = %.1f kN</td></tr>' ...
   '<tr><td>Result</td><td>strut S1 = %.1f kN; vertical tie V = %.1f kN; the beam bars carry T = %.1f kN</td></tr></table>'], ...
   Tk, th, Tk, cosd(th), M.Fs*kN, Tk, th, Tk, tand(th), M.V*kN, M.Fs*kN, M.V*kN, Tk);
w(['<table class="st"><tr><td>Step 3</td><td>Where the strut meets the beam bars (node N2)</td></tr>' ...
   '<tr><td>Rule</td><td>Geometry: the strut drops (z<sub>A1</sub> &minus; z<sub>bars</sub>) while it advances (z<sub>A1</sub> &minus; z<sub>bars</sub>)/tan&theta; towards the face.</td></tr>' ...
   '<tr><td>Numbers</td><td>drop = %g + %g = %g mm; advance = %g / %.3f = %.0f mm; u<sub>N2</sub> = %g &minus; %.0f = %.0f mm</td></tr>' ...
   '<tr><td>Result</td><td>N2 at u = %.0f mm from the cantilever face</td></tr></table>'], ...
   z1, -z2, z1 - z2, z1 - z2, tand(th), (z1 - z2)/tand(th), bp.u, (z1 - z2)/tand(th), M.u2, M.u2);
w(['<table class="st"><tr><td>Step 4</td><td>Tie A1: the two anchor rods</td></tr>' ...
   '<tr><td>Rule</td><td>23.7.2: F<sub>nt</sub> = A<sub>ts</sub> f<sub>y</sub>; check &phi;F<sub>nt</sub> &ge; T</td></tr>' ...
   '<tr><td>Numbers</td><td>&phi;F<sub>nt</sub> = 0.75 &times; 2 rods &times; %g mm&sup2; &times; %g MPa = %.1f kN; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], Ase, an.fya, phi*2*Ase*an.fya*kN, Tk, phi*2*Ase*an.fya*kN, ok_(M.dc(1)));
w(['<table class="st"><tr><td>Step 5</td><td>Tie of the beam top bars</td></tr>' ...
   '<tr><td>Rule</td><td>23.7.2: F<sub>nt</sub> = A<sub>ts</sub> f<sub>y</sub>, with the %d bars counted in section 5; check &phi;F<sub>nt</sub> &ge; T</td></tr>' ...
   '<tr><td>Numbers</td><td>&phi;F<sub>nt</sub> = 0.75 &times; %d bars &times; %.0f mm&sup2; &times; %g MPa = %.1f kN; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], M.n, M.n, Ab12s, P.fy, phi*M.n*Ab12s*P.fy*kN, Tk, phi*M.n*Ab12s*P.fy*kN, ok_(M.dc(2)));
w(['<table class="st"><tr><td>Step 6</td><td>Vertical tie V: the 2 far corner column bars &#216;%g (their hooks rest on the B1 nuts)</td></tr>' ...
   '<tr><td>Rule</td><td>23.7.2: &phi;F<sub>nt</sub> = 0.75 A<sub>ts</sub> f<sub>y</sub> &ge; V</td></tr>' ...
   '<tr><td>Numbers</td><td>&phi;F<sub>nt</sub> = 0.75 &times; 2 &times; %.0f mm&sup2; &times; %g MPa = %.1f kN; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], P.col.db, Acol, P.fy, phi*2*Acol*P.fy*kN, M.V*kN, phi*2*Acol*P.fy*kN, ok_(M.dc(3)));
w(['<table class="st"><tr><td>Step 7</td><td>Width of the strut S1 where it leaves B1</td></tr>' ...
   '<tr><td>Rule</td><td>Fig. R23.2.6b: w<sub>s</sub> = h<sub>B1</sub> cos&theta; + w<sub>V</sub> sin&theta;, with w<sub>V</sub> = %g mm, from the B1 face to the front of the column hooks that bring V in</td></tr>' ...
   '<tr><td>Numbers</td><td>w<sub>s</sub> = %g &times; %.3f + %g &times; %.3f = %.1f + %.1f = %.1f mm</td></tr>' ...
   '<tr><td>Result</td><td>w<sub>s</sub> = %.1f mm (it stays this wide in the plane down to N2)</td></tr></table>'], ...
   wV, bp.h, cosd(th), wV, sind(th), bp.h*cosd(th), wV*sind(th), M.ws, M.ws);
w(['<table class="st"><tr><td>Step 8</td><td>Node N2 on the beam bars: is the concrete there strong enough?</td></tr>' ...
   '<tr><td>Rule</td><td>23.9.1 and 23.9.2: allowed stress f<sub>ce</sub> = 0.85 &beta;<sub>c</sub> &beta;<sub>n</sub> f''<sub>c</sub>; &beta;<sub>n</sub> = 0.8 (one tie, Table 23.9.2(b)), &beta;<sub>c</sub> = 1 (no bearing plate, Table 23.4.3(b)(c)). ' ...
   'The strut arrives %.1f wide; across the joint it has widened from B1 (%g) to the group of bars, %.0f mm (R23.4.2).</td></tr>' ...
   '<tr><td>Numbers</td><td>allowed: &phi; f<sub>ce</sub> = 0.75 &times; 0.85 &times; 1 &times; 0.8 &times; %.2f = %.1f MPa<br>' ...
   'stress: S1 / (w<sub>s</sub> &times; width) = %.0f N / (%.1f mm &times; %.0f mm) = %.1f MPa; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], M.ws, bp.w, M.b2, fc, phi*M.fn2, M.Fs, M.ws, M.b2, M.Fs/(M.ws*M.b2), M.Fs/(M.ws*M.b2), phi*M.fn2, ok_(M.dc(6)));
zone = M.ws/sind(th);
w(['<table class="st"><tr><td>Step 9</td><td>Are the beam bars long enough beyond N2, towards their hooks?</td></tr>' ...
   '<tr><td>Rule</td><td>23.8.3: the tie must be developed from where it leaves the node zone. The zone is w<sub>s</sub>/sin&theta; long along the bars; the hook needs l<sub>dh</sub> = %.0f mm (25.4.3, section 5); ' ...
   'the outside of the hooks is taken %g mm further out than drawn (Table 26.6.2.1 tolerance).</td></tr>' ...
   '<tr><td>Numbers</td><td>zone length = %.1f / %.3f = %.0f mm, half = %.0f mm; zone ends at u = %.0f &minus; %.0f = %.0f<br>' ...
   'hooks end at u = %g + %g = %g; length available = %.0f &minus; %g = %.0f mm; D/C = %.0f / %.0f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], H.ldh12, P.tol.ub, M.ws, sind(th), zone, zone/2, M.u2, zone/2, M.u2 - zone/2, ...
   P.cb.uh, P.tol.ub, P.cb.uh + P.tol.ub, M.u2 - zone/2, P.cb.uh + P.tol.ub, M.avail, H.ldh12, M.avail, ok_(M.dc(7)));
w('<p><b>Path 1 result, type E:</b> the worst check is %.2f (step %s). Every check passes.</p></div>', max(M.dc([1 2 3 6 7])), ifelse(M.dc(6) >= M.dc(7), '8', '9'));

% ---------------- path 2
w('<h3>9.2 Path 2: from the back plate diagonally down to the end plate''s push</h3><div class="calc" style="max-width:1000px">');
w(['<table class="st"><tr><td>Step 1</td><td>Where the end plate pushes on the face (node N3)</td></tr>' ...
   '<tr><td>Rule</td><td>The compression of the end plate is the bearing block of plate_check section 3 (AISC DG1): length Y from the bottom edge of the plate, width %g; its centre is the node.</td></tr>' ...
   '<tr><td>Numbers</td><td>bottom edge at z = %g; Y = %.0f mm; z<sub>N3</sub> = %g + %.0f / 2 = %.0f</td></tr>' ...
   '<tr><td>Result</td><td>N3 at u = 0, z = %.0f; it pushes with C = T = %.1f kN</td></tr></table>'], P.ep.w, Y.ep_bot, q.Y, Y.ep_bot, q.Y, q.z3, q.z3, Tk);
w(['<table class="st"><tr><td>Step 2</td><td>Angle of the strut from B1 to N3</td></tr>' ...
   '<tr><td>Rule</td><td>Fixed by the two nodes: tan&theta; = drop / distance; 23.2.7 asks 25&#176; to 65&#176;</td></tr>' ...
   '<tr><td>Numbers</td><td>drop = %g + %.0f = %.0f mm; distance = %g mm; &theta; = atan(%.0f / %g) = %.1f&#176;</td></tr>' ...
   '<tr><td>Result</td><td>&theta; = %.1f&#176; (within 25&#176; to 65&#176;)</td></tr></table>'], z1, -q.z3, z1 - q.z3, bp.u, z1 - q.z3, bp.u, q.theta, q.theta);
w(['<table class="st"><tr><td>Step 3</td><td>Forces</td></tr>' ...
   '<tr><td>Rule</td><td>As in path 1: S = T / cos&theta;, V = T tan&theta;</td></tr>' ...
   '<tr><td>Numbers</td><td>S = %.1f / %.3f = %.1f kN; V = %.1f &times; %.3f = %.1f kN</td></tr>' ...
   '<tr><td>Result</td><td>strut %.1f kN; column bars %.1f kN; the column below takes the moment</td></tr></table>'], Tk, cosd(q.theta), q.Fs*kN, Tk, tand(q.theta), q.V*kN, q.Fs*kN, q.V*kN);
w(['<table class="st"><tr><td>Step 4</td><td>Ties: anchors and column bars</td></tr>' ...
   '<tr><td>Rule</td><td>23.7.2, as steps 4 and 6 of path 1</td></tr>' ...
   '<tr><td>Numbers</td><td>anchors: %.1f / %.1f; column bars: %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>anchors %s; column bars %s</td></tr></table>'], Tk, phi*2*Ase*an.fya*kN, q.V*kN, phi*2*Acol*P.fy*kN, ok_(q.dc(1)), ok_(q.dc(2)));
w(['<table class="st"><tr><td>Step 5</td><td>Node N3: bearing of the end plate on the face</td></tr>' ...
   '<tr><td>Rule</td><td>23.9.2: &beta;<sub>n</sub> = 1.0 (only compression meets here, Table 23.9.2(a)); &beta;<sub>c</sub> = %.2f (a bearing plate on a wide face, Table 23.4.3(b)(a))</td></tr>' ...
   '<tr><td>Numbers</td><td>allowed: 0.75 &times; 0.85 &times; %.2f &times; 1.0 &times; %.2f = %.1f MPa<br>stress: %.0f N / (%.0f mm &times; %g mm) = %.1f MPa; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], q.bc3, q.bc3, fc, phi*q.fn3, M.T, q.Y, P.ep.w, M.T/(q.Y*P.ep.w), M.T/(q.Y*P.ep.w), phi*q.fn3, ok_(q.dc(5)));
w(['<table class="st"><tr><td>Step 6</td><td>The strut where it arrives at N3</td></tr>' ...
   '<tr><td>Rule</td><td>23.4.1 and 23.4.3: allowed 0.85 &beta;<sub>c</sub> &beta;<sub>s</sub> f''<sub>c</sub>, &beta;<sub>s</sub> = 0.75 (strut in a beam-column joint, Table 23.4.3(a)(e)); width w = Y cos&theta; (conservative)</td></tr>' ...
   '<tr><td>Numbers</td><td>w = %.0f &times; %.3f = %.1f mm<br>allowed: 0.75 &times; 0.85 &times; %.2f &times; 0.75 &times; %.2f = %.1f MPa<br>stress: %.0f N / (%.1f mm &times; %g mm) = %.1f MPa; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s. This ratio is the same at any load: the bearing block grows with the load at a fixed stress.</td></tr></table>'], ...
   q.Y, cosd(q.theta), q.ws3, q.bc3, fc, phi*q.fs3, q.Fs, q.ws3, P.ep.w, q.Fs/(q.ws3*P.ep.w), q.Fs/(q.ws3*P.ep.w), phi*q.fs3, ok_(q.dc(6)));
As3c = 3*Acol;  dcol = P.col.b - rc;  a3c = As3c*P.fy/(0.85*fc*P.col.b);  phiMc = 0.9*As3c*P.fy*(dcol - a3c/2);
Mcol = hypot(Y.Mu, P.frame.Mcol*1e6);
w(['<table class="st"><tr><td>Step 7</td><td>The column below takes the moment</td></tr>' ...
   '<tr><td>Rule</td><td>22.4, no axial force; conservative: only the 3 bars on the tension face, no compression steel. Demand: all of the cantilever, plus the frame moment at right angles (as in revision 2).</td></tr>' ...
   '<tr><td>Numbers</td><td>a = %.0f &times; %g / (0.85 &times; %.2f &times; %g) = %.1f mm<br>&phi;M<sub>n</sub> = 0.9 &times; %.0f &times; %g &times; (%g &minus; %.1f/2) = %.1f kN m<br>' ...
   'demand = &radic;(%.1f&sup2; + %.1f&sup2;) = %.1f kN m; D/C = %.1f / %.1f</td></tr>' ...
   '<tr><td>Result</td><td>%s</td></tr></table>'], As3c, P.fy, fc, P.col.b, a3c, As3c, P.fy, dcol, a3c, phiMc*1e-6, Y.Mu*1e-6, P.frame.Mcol, Mcol*1e-6, Mcol*1e-6, phiMc*1e-6, ok_(Mcol/phiMc));
w('<p><b>Path 2 result, type E:</b> the worst check is %.2f. Every check passes.</p></div>', max(q.dc([1 2 4 5 6])));

% ---------------- N1: the anchor head
w('<h3>9.3 Node N1 at the back plate: the head of the anchors (information only)</h3><div class="calc" style="max-width:1000px">');
w(['<table class="st"><tr><td>What</td><td>The concrete just in front of B1, where both paths start</td></tr>' ...
   '<tr><td>Which rule</td><td>B1 is the head of the anchors. Chapter 17 checks a head with equations from tests on heads: pullout 17.6.3 <b>%s</b>, side blowout towards the pedestal top 17.6.4 <b>%s</b>. ' ...
   'Caveat: 17.1.5 leaves out one plate joining two anchors, so these are the closest checks, not a formal fit (decision of 2026-10-02: keep one B1).</td></tr>' ...
   '<tr><td>Chapter 23 (for comparison)</td><td>allowed: 0.75 &times; 0.85 &times; &beta;<sub>c</sub> %.2f &times; &beta;<sub>n</sub> 0.6 (two ties meet: anchors and column bars, Table 23.9.2(c)) &times; %.2f = %.1f MPa<br>' ...
   'stress on the B1 face: %.0f N / %.0f mm&sup2; = %.1f MPa; D/C = %.2f (with &beta;<sub>n</sub> = 0.8: %.2f)</td></tr>' ...
   '<tr><td>Why only information</td><td>The chapter 23 limit (about 1.0 f''<sub>c</sub>) is calibrated on nodes at bearing plates of deep beams; at an anchor head chapter 17 allows 8 f''<sub>c</sub> from tests. ' ...
   'The head has thin cover only towards the top, and the blowout check covers exactly that.</td></tr></table>'], ...
   ok_(xp{4}(1)/xp{5}(1)), ok_(xb{4}(1)/xb{5}(1)), M.bc, fc, phi*M.fn1, M.T, An1, M.T/An1, M.dc(4), S8(1).dc(4));
w('</div>');
w('<h3>9.4 All types</h3><div class="tw"><table><tr><th>Element</th><th>Clause</th><th class="n">E</th><th class="n">C1</th><th class="n">CX</th><th class="n">CY</th></tr>');
nm9 = {'Path 1: &theta; chosen (&#176;)', '23.2.7'; 'Tie A1', '23.7.2'; 'Tie, beam bars', '23.7.2'; 'Tie V, column bars', '23.7.2'; 'N1, B1 face (information, head: ch. 17)', '23.9.1'; ...
       'S1 at N1 (information, head: ch. 17)', '23.4.1'; 'N2 (S1 face)', '23.9.1'; 'Beam bars developed beyond N2', '23.8.3, 25.4.3'; '<b>Path 1, largest</b>', ''; 'Path 1, largest with N1 (information)', '';
       'Path 2: &theta; (&#176;)', '23.2.7'; 'Path 2: tie V', '23.7.2'; 'Path 2: strut at N1 (information, head: ch. 17)', '23.4.1'; 'Path 2: N3 face', '23.9.1'; 'Path 2: strut at N3', '23.4.1'; 'Path 2, largest with N1 (information)', ''; '<b>Path 2, largest</b>', ''};
info9 = [5 6 10 13 16];
for i = 1:numel(nm9)/2
    w('<tr><td>%s</td><td>%s</td>', nm9{i,1}, nm9{i,2});
    for j = 1:4
        if i == 1, v = S6(j).theta; w('<td class="n">%.1f</td>', v); continue; end
        if i == 11, v = S6(j).p2.theta; w('<td class="n">%.1f</td>', v); continue; end
        q2 = S6(j).p2.dc;
        if i <= 8, v = S6(j).dc(i - 1); elseif i == 9, v = max(S6(j).dc([1 2 3 6 7])); elseif i == 10, v = max(S6(j).dc);
        elseif i == 12, v = q2(2); elseif i == 13, v = q2(4); elseif i == 14, v = q2(5); elseif i == 15, v = q2(6);
        elseif i == 16, v = max(q2(1:6)); else, v = max(q2([1 2 4 5 6])); end
        if any(i == info9), w('<td class="n" style="color:#777">%.2f</td>', v); else, w('<td class="n %s">%.2f</td>', ifelse(v <= 1, 'ok', 'ng'), v); end
    end
    w('</tr>');
end
w('</table></div>');

% larger back plates
w('<h3>9.5 If the head were checked by chapter 23 too (information, type E, &beta;<sub>n</sub> = 0.6)</h3><div class="tw"><table><tr><th>B1</th><th class="n">N1 face</th><th class="n">S1 at N1</th><th class="n">N2</th><th class="n">bars beyond N2</th><th class="n">STM largest</th><th class="n">STM largest CY</th><th class="n">B1 itself: through the hole (section 3)</th></tr>');
for hw = [45 120; 60 120; 45 160; 60 160; 60 200]'
    P2 = P;  P2.bp.h = hw(1);  P2.bp.w = hw(2);  R2 = ca_calc(P2);  Sx = ca_stm(P2, R2, 0.6);  d1 = Sx(1).dc;   % theta still chosen without N1
    rh_ = R2.rows(find(strncmp(R2.rows(:,2), 'Back plate through the hole', 27), 1), :);  dh = rh_{4}(1)/rh_{5}(1);
    if all(hw' == [60 120]), big = [max(d1), max(arrayfun(@(q) max(q.dc), Sx))]; end
    w('<tr><td>PL %gx%gx%g</td><td class="n">%.2f</td><td class="n">%.2f</td><td class="n">%.2f</td><td class="n">%.2f</td><td class="n %s">%.2f</td><td class="n">%.2f</td><td class="n %s">%.2f</td></tr>', ...
      bp.t, hw(1), hw(2), d1(4), d1(5), d1(6), d1(7), ifelse(max(d1) <= 1, 'ok', 'ng'), max(d1), max(Sx(4).dc), ifelse(dh <= 1, 'ok', 'ng'), dh);
end
w('</table></div>');
w(['<div class="calc" style="max-width:1150px"><p><b>Reading.</b> Every tie is comfortable (0.3 to 0.65), so the steel of both load paths is complete and strong enough: that is what R17.5.2.1 asks a strut-and-tie model to prove. ' ...
   'The concrete away from the head also passes: path 1 at %.2f (E: the node on the beam bars and the bar length past it, which eases as soon as path 2 takes part of T), path 2 at %.2f. ' ...
   'At the head itself the chapter 23 node limit would give %.2f at E; a taller plate (PL 12x60x120) would bring it to %.2f, but the head is checked by chapter 17 (pullout %.2f, blowout %.2f), and the design keeps PL 12x45x120 (user, 2026-10-04).</p></div>'], ...
   max(S6(1).dc([1 2 3 6 7])), max(S6(1).p2.dc([1 2 4 5 6])), S6(1).dc(4), big(1), xp{4}(1)/xp{5}(1), xb{4}(1)/xb{5}(1));
w('<div class="calc" style="max-width:1150px"><h3>9.6 Review of the model (what was checked, what is assumed)</h3><ol>');
w('<li><b>Equilibrium</b> (23.2.4): path 1, the local couple T (z<sub>A1</sub> &minus; z<sub>bars</sub>) = %.2f kN m equals V (u<sub>N1</sub> &minus; u<sub>N2</sub>) = %.2f kN m, taken by the column; path 2, T (z<sub>A1</sub> &minus; z<sub>N3</sub>) = %.2f kN m equals V u<sub>N1</sub> = %.2f kN m and equals M<sub>u</sub> = %.2f kN m.</li>', ...
  M.T*(z1 - z2)*1e-6, M.V*(bp.u - M.u2)*1e-6, M.T*(z1 - M.p2.z3)*1e-6, M.p2.V*bp.u*1e-6, Y.Mu*1e-6);
w('<li><b>Angles</b> (23.2.7): every strut 25&#176; to 65&#176; from the horizontal ties and the vertical tie. <b>Factors</b>: &phi; 0.75 (Table 21.2.1(g)); &beta;<sub>s</sub> 0.75 for struts in a beam-column joint (Table 23.4.3(a)(e), no 23.5 reinforcement needed); &beta;<sub>n</sub> 1.0 / 0.8 / 0.6 by the number of ties (Table 23.9.2); &beta;<sub>c</sub> 2 only at bearing faces (B1, the end plate), 1 elsewhere (Table 23.4.3(b)).</li>');
w('<li><b>Assumed geometry</b>: N2 lies on the lower layer of beam bars (as in section 5); the strut reaching N2 widens out of the plane to the bar group (R23.4.2, tapered strut); at N3 the bearing block is the DG1 one; the vertical struts S2 and S3 into the column are wide and not checked; the width w<sub>V</sub> = %g at N1 (where the hooks bring V in) matters only for the information checks at the head.</li>', wV);
w('<li><b>23.11 not applied</b>: the strut-and-tie model carries the cantilever (gravity and E<sub>v</sub>), not the frame''s lateral force, as for the anchors in 17.10 (section 1 of the report: no E<sub>h</sub> on the cantilever); the frame is ordinary (user).</li>');
w('<li><b>What it does not replace</b>: chapter 17 for the anchors and their head, chapter 25 for the beam bars as anchor reinforcement (sections 2 to 6), and the beam and joint checks of the report.</li>');
w('</ol></div>');
w('</body></html>');
fclose(fid);
end

function r = ifelse(a, b, c)
if a, r = b; else, r = c; end
end

